View.TextArea:
Label: {
  default: { touchEnabled: false }
},

ScrollView: {
  default: {
    contentWidth: 'Ti.UI.FILL',
    contentHeight: 'Ti.UI.SIZE'
  },
  android: { scrollType: 'vertical' }
},

Button: {
  android: { backgroundColor: 'transparent' }
}

'.gallery': {
  DEFAULT: {
    height: 'Ti.UI.SIZE'
  },
  ios: {
    clipMode: 'Ti.UI.iOS.CLIP_MODE_ENABLED'
  },
  android: {
    hiddenBehavior:
      'Ti.UI.HIDDEN_BEHAVIOR_GONE'
  },
  handheld: { width: '250px' },
  tablet: { width: '500px' }
}

TextField: {
  DEFAULT: {
    top: 10, left: 20,
    right: 20, bottom: 0
  },
  '[if=Alloy.Globals.iPhoneX]': {
    bottom: 'Alloy.CFG.iPhoneXNotchSize'
  },
  android: { touchFeedback: true }
}

// Constants → quoted strings clipMode: 'Ti.UI.iOS.CLIP_MODE_ENABLED' scrollType: 'vertical' contentHeight: 'Ti.UI.SIZE'
// Colors → hex, rgb, rgba, or name backgroundColor: '#53606b' borderColor: 'rgba(100,200,50,0.5)'
// Spacing → em, rem, %, px, dp, cm, in width: '300px' // passed through height: '1.5rem' // → 24 (value × 16) top: '10dp' // → 10 (unit stripped)
